      `[${account.accountId}] weixin bot token expired — attempting automatic QR re-login...`,
    );
    // Attempt automatic re-login via QR code. This requires user interaction (scan QR).
    // If it fails, the error propagates and the gateway will surface it to the user.
    try {
      const qrResult = await startWeixinLoginWithQr({
        accountId: account.accountId,
        apiBaseUrl: account.baseUrl,
        botType: DEFAULT_ILINK_BOT_TYPE,
        force: true,
        timeoutMs: 480_000,
        verbose: true,
      });
      if (!qrResult.qrcodeUrl) {
        throw new Error(qrResult.message || "Failed to start QR re-login");
      }
      ctx.log?.info?.(`[${account.accountId}] QR re-login started. Please scan the QR code to reconnect.`);
      const loginResult = await waitForWeixinLogin({
        sessionKey: qrResult.sessionKey,
        apiBaseUrl: account.baseUrl,
        timeoutMs: 480_000,
        botType: DEFAULT_ILINK_BOT_TYPE,
      });
      if (loginResult.connected && loginResult.botToken && loginResult.accountId) {
        const normalizedId = normalizeAccountId(loginResult.accountId);
        saveWeixinAccount(normalizedId, {
          token: loginResult.botToken,
          baseUrl: loginResult.baseUrl,
          userId: loginResult.userId,
        });
        registerWeixinAccountId(normalizedId);
        if (loginResult.userId) {
          clearStaleAccountsForUserId(normalizedId, loginResult.userId, clearContextTokensForAccount);
        }
        ctx.log?.info?.(`[${account.accountId}] ✅ Automatic re-login succeeded`);
        aLog.info(`Automatic re-login succeeded for account=${normalizedId}`);
        // Re-resolve the account with the new token
        const updatedAccount = await import("./auth/accounts.js").then(m =>
          m.resolveWeixinAccount(ctx.cfg!, normalizedId),
        );
        ctx.setStatus?.({ accountId: normalizedAccountId, running: true, lastStartAt: Date.now(), lastEventAt: Date.now() });
        return monitorWeixinProvider({
          baseUrl: updatedAccount.baseUrl,
          cdnBaseUrl: updatedAccount.cdnBaseUrl,
          token: updatedAccount.token,
          accountId: updatedAccount.accountId,
          config: ctx.cfg,
          runtime: ctx.runtime,
          abortSignal: ctx.abortSignal,
          setStatus: ctx.setStatus,
        });
      } else {
        throw new Error(loginResult.message || "Re-login did not complete");
      }
    } catch (reauthErr) {
      const msg = `Automatic re-login failed: ${String(reauthErr)}. Please re-login manually: openclaw channels login --channel openclaw-weixin`;
      aLog.error(msg);
      ctx.log?.error?.(`[${account.accountId}] ${msg}`);
      ctx.setStatus?.({
        accountId: account.accountId,
        running: false,
        lastError: msg,
        lastEventAt: Date.now(),
      });
      throw new Error(msg);
    }
  }
  aLog.error(`account not configured`);
  ctx.log?.error?.(
    `[${account.accountId}] weixin not logged in — run: openclaw channels login --channel openclaw-weixin`,
  );
  ctx.setStatus?.({ accountId: account.accountId, running: false });
  throw new Error("weixin not configured: missing token");
}

